package com.shilapi.xcertplay

import android.content.Context

/**
 * Identifies the APK that is running: short git hash and build time, generated by the build.
 *
 * versionCode and versionName are deliberately identical across test builds, and
 * PackageInfo.lastUpdateTime is the install time rather than the build time, so this is the only
 * field that can tell two builds apart in a diagnostic report.
 */
object BuildStamp {
    private const val ASSET = "build_stamp.txt"

    fun read(context: Context): String = runCatching {
        context.assets.open(ASSET).bufferedReader().use { it.readText().trim() }
    }.getOrDefault("unknown")
}
